-- Prompts : le paragraphe "Contexte" décrit désormais la situation du point de
-- vue de l'utilisateur ("Je suis...", "Je gère...") au lieu de l'attribuer à
-- l'IA ("Tu es...", "Tu gères..."). Le rôle donné à l'IA ("Tu es un
-- assistant...") et les consignes qui lui sont adressées restent en "tu".
-- La ligne "Colle ici les données du Cas fictif N de la tâche FXX, disponibles
-- dans exercices-42-taches.md (...)" renvoyait à un fichier interne : elle est
-- remplacée par "Tu trouveras les données du cas pratique (...) à la fin de ce
-- message.", puisque l'application ajoute les données à la fin du prompt copié.
-- Chaque update ne touche que les lignes qui contiennent le texte d'origine :
-- sans effet si la migration est exécutée une seconde fois.

update prompts set contenu = replace(contenu, $v$Tu es assistant(e) de direction chez Méridia Architecture (8 salariés, Lyon). Tu reviens de deux jours de congé et trouves 11 emails non lus dans la boîte partagée "contact@meridia-archi.fr".$v$, $v$Je suis assistant(e) de direction chez Méridia Architecture (8 salariés, Lyon). Je reviens de deux jours de congé et trouve 11 emails non lus dans la boîte partagée "contact@meridia-archi.fr".$v$) where strpos(contenu, $v$Tu es assistant(e) de direction chez Méridia Architecture (8 salariés, Lyon). Tu reviens de deux jours de congé et trouves 11 emails non lus dans la boîte partagée "contact@meridia-archi.fr".$v$) > 0;
update prompts set contenu = replace(contenu, $v$Colle ici les données du Cas fictif 1 de la tâche F01, disponibles dans exercices-42-taches.md (la liste des 11 emails).$v$, $v$Tu trouveras les données du cas pratique (la liste des 11 emails) à la fin de ce message.$v$) where strpos(contenu, $v$Colle ici les données du Cas fictif 1 de la tâche F01, disponibles dans exercices-42-taches.md (la liste des 11 emails).$v$) > 0;
